const canvas = root.querySelector("canvas");
const ctx = canvas.getContext("2d");
const titleNode = root.querySelector(".title");
const subNode = root.querySelector(".sub");
const footerNode = root.querySelector(".footer");
const sceneDots = Array.from(root.querySelectorAll(".scene-dot"));

let width = 1;
let height = 1;

const SCENE_MODEL_MS = 5000;
const SCENE_WIND_MS = 6200;
const SCENE_RPM_MS = 5200;
const SCENE_TOTAL_MS = SCENE_MODEL_MS + SCENE_WIND_MS + SCENE_RPM_MS;
const CANONICAL_CAMERA_PITCH = -0.94;
const CANONICAL_SPIN_RATE = 0.00115;
const CANONICAL_SCALE = 0.82;
const TRANSITION_MS = 620;

function resize(){
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = Math.max(1, Math.round(rect.width * dpr));
  const h = Math.max(1, Math.round(rect.height * dpr));
  if(canvas.width !== w || canvas.height !== h){ canvas.width = w; canvas.height = h; width = w; height = h; }
  return dpr;
}
function clamp01(v){ return Math.max(0, Math.min(1, v)); }
function smooth(v){ const t=clamp01(v); return t*t*(3-2*t); }
function fadeWindow(local, duration){ return Math.min(smooth(local/TRANSITION_MS), smooth((duration-local)/TRANSITION_MS)); }
function setScene(index,title,sub,footer){
  titleNode.textContent=title; subNode.textContent=sub; footerNode.textContent=footer||"";
  sceneDots.forEach((dot,i)=>dot.classList.toggle("active",i===index));
}

function v3(x=0,y=0,z=0){ return [x,y,z]; }
function add(a,b){ return [a[0]+b[0],a[1]+b[1],a[2]+b[2]]; }
function mul(a,s){ return [a[0]*s,a[1]*s,a[2]*s]; }
function cross(a,b){ return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]; }
function len(a){ return Math.hypot(a[0],a[1],a[2]); }
function norm(a){ const l=len(a); return l>1e-9?mul(a,1/l):v3(); }
function avgPoints(poly){
  if(!poly || !poly.length) return v3();
  let s=v3(); poly.forEach(p=>{s=add(s,[Number(p[0])||0,Number(p[1])||0,Number(p[2])||0]);});
  return mul(s,1/poly.length);
}
function qRotate(q,v){
  const w=q[0], x=q[1], y=q[2], z=q[3];
  const tx=2*(y*v[2]-z*v[1]);
  const ty=2*(z*v[0]-x*v[2]);
  const tz=2*(x*v[1]-y*v[0]);
  return [v[0]+w*tx+(y*tz-z*ty), v[1]+w*ty+(z*tx-x*tz), v[2]+w*tz+(x*ty-y*tx)];
}
function qInverseRotate(q,v){ return qRotate([q[0],-q[1],-q[2],-q[3]],v); }

const allPoints = panels.concat(bodyQuads).flat();
const maxRadius = Math.max(0.01,...allPoints.map(p=>Math.hypot(Number(p[0])||0,Number(p[1])||0,Number(p[2])||0)));

function projectPoint(point,spin,dpr,scaleMul=1,offsetX=0,offsetY=0,cameraPitch=CANONICAL_CAMERA_PITCH){
  const px=Number(point[0])||0, py=Number(point[1])||0, pz=Number(point[2])||0;
  const cs=Math.cos(spin), sn=Math.sin(spin);
  const x=px*cs-py*sn, y=px*sn+py*cs, z=pz;
  const yaw=-0.62, pitch=cameraPitch;
  const cy=Math.cos(yaw), sy=Math.sin(yaw);
  const x1=x*cy-y*sy, y1=x*sy+y*cy;
  const cp=Math.cos(pitch), sp=Math.sin(pitch);
  const y2=y1*cp-z*sp, z2=y1*sp+z*cp;
  const modelScale=Math.min(width,height)*0.33/maxRadius*scaleMul;
  return [width*0.52+offsetX+x1*modelScale,height*0.56+offsetY-y2*modelScale,z2,dpr];
}

function drawRotor(now,alpha,dpr,opts={}){
  if(!allPoints.length) return;
  const spin = Number.isFinite(opts.spin) ? opts.spin : now*CANONICAL_SPIN_RATE;
  const scaleMul = opts.scaleMul || 1;
  const offsetX = opts.offsetX || 0;
  const offsetY = opts.offsetY || 0;
  const polys=panels.map(poly=>({kind:"blade",poly})).concat(bodyQuads.map(poly=>({kind:"body",poly}))).map(item=>{
    const projected=item.poly.map(p=>projectPoint(p,spin,dpr,scaleMul,offsetX,offsetY,opts.cameraPitch ?? CANONICAL_CAMERA_PITCH));
    return {projected,kind:item.kind,depth:projected.reduce((s,p)=>s+p[2],0)/Math.max(1,projected.length)};
  }).sort((a,b)=>a.depth-b.depth);
  ctx.save(); ctx.globalAlpha=alpha;
  for(const item of polys){
    if(!item.projected.length) continue;
    ctx.beginPath(); item.projected.forEach((p,i)=>{if(i===0)ctx.moveTo(p[0],p[1]);else ctx.lineTo(p[0],p[1]);}); ctx.closePath();
    ctx.fillStyle=item.kind==="body"?"#e5e5e7":"#f5f5f7";
    ctx.strokeStyle=item.kind==="body"?"#6e6e73":"#3a3a3c";
    ctx.lineWidth=(item.kind==="body"?0.9:1.0)*dpr; ctx.fill(); ctx.stroke();
  }
  ctx.restore();
}

function getWindSample(local,duration){
  if(!samples.length) return null;
  const p=0.58+0.34*smooth(clamp01((local-TRANSITION_MS*0.25)/Math.max(1,duration-TRANSITION_MS*0.8)));
  return samples[Math.min(samples.length-1,Math.floor(p*(samples.length-1)))];
}
function sampleState(s){
  if(!s) return null;
  const q=[Number(s[4])||1,Number(s[5])||0,Number(s[6])||0,Number(s[7])||0];
  const vWorld=s.length>=12?[Number(s[9])||0,Number(s[10])||0,Number(s[11])||0]:[0,0,-1];
  const omega=s.length>=15?[Number(s[12])||0,Number(s[13])||0,Number(s[14])||0]:[0,0,(Number(s[8])||0)*2*Math.PI/60];
  return {time:Number(s[0])||0,rpm:Number(s[8])||0,q,vBody:qInverseRotate(q,vWorld),omega};
}

function drawArrow2D(a,b,alpha,dpr,strong=false){
  const dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy); if(l<2*dpr)return;
  const ux=dx/l,uy=dy/l; const head=(strong?6:4)*dpr;
  ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=strong?"#1d1d1f":"#86868b";ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=(strong?1.35:0.9)*dpr;
  ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke();
  ctx.beginPath();ctx.moveTo(b[0],b[1]);ctx.lineTo(b[0]-ux*head-uy*head*.5,b[1]-uy*head+ux*head*.5);ctx.lineTo(b[0]-ux*head+uy*head*.5,b[1]-uy*head-ux*head*.5);ctx.closePath();ctx.fill();ctx.restore();
}

function drawWindReference(alpha,dpr){
  const x=width-38*dpr;
  const midY=height*0.43;
  const arrow=34*dpr;
  ctx.save();
  ctx.globalAlpha=alpha;
  ctx.textAlign="right";
  ctx.fillStyle="#6e6e73";
  ctx.font=`${9*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;
  ctx.fillText("relative airflow · +Z",x-10*dpr,midY-arrow-5*dpr);
  drawArrow2D([x,midY],[x,midY-arrow],alpha,dpr,true);
  ctx.fillText("descent · −Z",x-10*dpr,midY+arrow+12*dpr);
  drawArrow2D([x,midY],[x,midY+arrow],alpha*.72,dpr,false);
  ctx.restore();
}

function drawRotationAxis(spin,alpha,dpr,scaleMul,offsetY,omegaZ=null,showEnds=false){
  const extent=Math.max(maxRadius*.72,0.025);
  const a=projectPoint([0,0,-extent],spin,dpr,scaleMul,0,offsetY,CANONICAL_CAMERA_PITCH);
  const b=projectPoint([0,0, extent],spin,dpr,scaleMul,0,offsetY,CANONICAL_CAMERA_PITCH);
  const c=projectPoint([0,0,0],spin,dpr,scaleMul,0,offsetY,CANONICAL_CAMERA_PITCH);
  ctx.save();
  ctx.globalAlpha=alpha*.78;
  ctx.strokeStyle="#86868b";
  ctx.lineWidth=.9*dpr;
  ctx.setLineDash([4*dpr,4*dpr]);
  ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle="#6e6e73";
  ctx.font=`${9*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;
  ctx.textAlign="left";
  ctx.fillText("Z · rotation axis",b[0]+7*dpr,b[1]-2*dpr);
  if(showEnds){
    ctx.font=`600 ${8.5*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;
    ctx.fillText("TOP  +Z",b[0]+7*dpr,b[1]+11*dpr);
    ctx.fillText("BOTTOM  −Z",a[0]+7*dpr,a[1]-5*dpr);
  }

  if(Number.isFinite(omegaZ) && Math.abs(omegaZ)>1e-6){
    const r=18*dpr;
    const clockwise=omegaZ<0;
    const start=clockwise?Math.PI*.15:Math.PI*.85;
    const end=clockwise?Math.PI*1.65:-Math.PI*.65;
    ctx.strokeStyle="#6e6e73";
    ctx.lineWidth=1*dpr;
    ctx.beginPath();ctx.arc(c[0],c[1],r,start,end,clockwise);ctx.stroke();
    const ex=c[0]+Math.cos(end)*r, ey=c[1]+Math.sin(end)*r;
    const tangent=end+(clockwise?-Math.PI/2:Math.PI/2);
    const hx=Math.cos(tangent),hy=Math.sin(tangent),head=5*dpr;
    ctx.fillStyle="#6e6e73";
    ctx.beginPath();ctx.moveTo(ex,ey);ctx.lineTo(ex-hx*head-hy*head*.55,ey-hy*head+hx*head*.55);ctx.lineTo(ex-hx*head+hy*head*.55,ey-hy*head-hx*head*.55);ctx.closePath();ctx.fill();
  }
  ctx.restore();
}

function drawModelReference(spin,alpha,dpr,scaleMul,offsetY){
  drawRotationAxis(spin,alpha,dpr,scaleMul,offsetY,null,true);
  const x=width-38*dpr;
  const midY=height*0.43;
  const arrow=34*dpr;
  ctx.save();
  ctx.globalAlpha=alpha*.78;
  ctx.textAlign="right";
  ctx.fillStyle="#6e6e73";
  ctx.font=`${9*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;
  ctx.fillText("descent · −Z",x-10*dpr,midY+arrow+12*dpr);
  drawArrow2D([x,midY],[x,midY+arrow],alpha*.72,dpr,false);
  ctx.restore();
}

function drawTunnelStreamlines(flow,spin,now,alpha,dpr,cameraPitch){
  const n=norm(flow); if(len(n)<1e-6)return;
  const o=projectPoint([0,0,0],spin,dpr,CANONICAL_SCALE,0,8*dpr,cameraPitch);
  const e=projectPoint(mul(n,maxRadius*.65),spin,dpr,CANONICAL_SCALE,0,8*dpr,cameraPitch);
  let dx=e[0]-o[0],dy=e[1]-o[1]; const dl=Math.hypot(dx,dy); if(dl<1)return; dx/=dl;dy/=dl;
  const px=-dy,py=dx;
  const span=Math.hypot(width,height)*0.72;
  const phase=((now*0.07*dpr)% (42*dpr));
  ctx.save();ctx.globalAlpha=alpha*0.72;ctx.strokeStyle="#d2d2d7";ctx.lineWidth=0.8*dpr;
  for(let i=-7;i<=7;i++){
    const off=i*19*dpr;
    for(let k=-2;k<=2;k++){
      const along=k*42*dpr+phase;
      const cx=width*.52+px*off+dx*(along-84*dpr);
      const cy=height*.57+py*off+dy*(along-84*dpr);
      const ax=cx-dx*13*dpr, ay=cy-dy*13*dpr, bx=cx+dx*13*dpr, by=cy+dy*13*dpr;
      ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(bx,by);ctx.stroke();
      if(((i+k)&1)===0){
        const head=2.6*dpr;
        ctx.fillStyle="#d2d2d7";
        ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(bx-dx*head-dy*head*.55,by-dy*head+dx*head*.55);ctx.lineTo(bx-dx*head+dy*head*.55,by-dy*head-dx*head*.55);ctx.closePath();ctx.fill();
      }
    }
  }
  ctx.restore();
}

function drawWindScene(now,local,duration,alpha,dpr){
  const raw=getWindSample(local,duration); const st=sampleState(raw); if(!st){drawRotor(now,alpha,dpr);return;}
  const spin=now*CANONICAL_SPIN_RATE;
  const scaleMul=CANONICAL_SCALE, offsetY=8*dpr;
  const centerFlow=mul(st.vBody,-1);
  drawTunnelStreamlines(centerFlow,spin,now,alpha,dpr,CANONICAL_CAMERA_PITCH);
  drawRotor(now,alpha,dpr,{spin,scaleMul,offsetY,cameraPitch:CANONICAL_CAMERA_PITCH});
  drawRotationAxis(spin,alpha,dpr,scaleMul,offsetY,st.omega[2],true);

  let maxSpeed=0; const bladeFlows=[];
  panels.forEach((poly,i)=>{
    if(i%2!==0)return;
    const c=avgPoints(poly); const localMotion=add(st.vBody,cross(st.omega,c)); const flow=mul(localMotion,-1); const speed=len(flow);
    maxSpeed=Math.max(maxSpeed,speed); bladeFlows.push({c,flow,speed});
  });
  maxSpeed=Math.max(maxSpeed,len(centerFlow),0.1);
  bladeFlows.forEach(item=>{
    const a=projectPoint(item.c,spin,dpr,scaleMul,0,offsetY,CANONICAL_CAMERA_PITCH);
    const direction=norm(item.flow); const modelStep=maxRadius*(0.18+0.34*item.speed/maxSpeed);
    const b=projectPoint(add(item.c,mul(direction,modelStep)),spin,dpr,scaleMul,0,offsetY,CANONICAL_CAMERA_PITCH);
    drawArrow2D(a,b,alpha*.9,dpr,true);
  });

  bodySegments.forEach(seg=>{
    const center=Array.isArray(seg)&&Array.isArray(seg[0])?seg[0]:seg;
    const c=Array.isArray(center)?[Number(center[0])||0,Number(center[1])||0,Number(center[2])||0]:v3();
    const localMotion=add(st.vBody,cross(st.omega,c));const flow=mul(localMotion,-1);const direction=norm(flow);
    const a=projectPoint(c,spin,dpr,scaleMul,0,offsetY,CANONICAL_CAMERA_PITCH);
    const b=projectPoint(add(c,mul(direction,maxRadius*.24)),spin,dpr,scaleMul,0,offsetY,CANONICAL_CAMERA_PITCH);
    drawArrow2D(a,b,alpha*.75,dpr,false);
  });

  drawWindReference(alpha,dpr);
  ctx.save();ctx.globalAlpha=alpha;ctx.textAlign="right";ctx.fillStyle="#1d1d1f";ctx.font=`600 ${12*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;
  ctx.fillText(`${st.rpm.toFixed(0)} rpm`,width-24*dpr,height-45*dpr);
  ctx.fillStyle="#86868b";ctx.font=`${10*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;
  ctx.fillText(`t = ${st.time.toFixed(2)} s · local relative airflow`,width-24*dpr,height-28*dpr);ctx.restore();
}

function drawRpmScene(local,duration,alpha,dpr){
  if(samples.length<2)return;
  const left=48*dpr,right=width-28*dpr,top=Math.max(78*dpr,height*.27),bottom=height-46*dpr;
  const chartW=Math.max(1,right-left),chartH=Math.max(1,bottom-top);
  const tmax=Math.max(.001,...samples.map(s=>Number(s[0])||0));
  const rpmmax=Math.max(1,...samples.map(s=>Number(s[8])||0));
  const progress=smooth(clamp01((local-TRANSITION_MS*.35)/Math.max(1,duration-TRANSITION_MS*1.2))); const drawUntil=tmax*progress;
  ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle="#eeeeef";ctx.lineWidth=1*dpr;
  for(let i=1;i<=3;i++){const y=top+chartH*i/4;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();}
  ctx.strokeStyle="#d2d2d7";ctx.beginPath();ctx.moveTo(left,top);ctx.lineTo(left,bottom);ctx.lineTo(right,bottom);ctx.stroke();
  ctx.fillStyle="#86868b";ctx.font=`${10*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;ctx.textAlign="left";ctx.fillText("RPM",left,top-10*dpr);ctx.textAlign="right";ctx.fillText(`${tmax.toFixed(2)} s`,right,bottom+20*dpr);
  ctx.strokeStyle="#1d1d1f";ctx.lineWidth=2*dpr;ctx.lineJoin="round";ctx.lineCap="round";ctx.beginPath();let last=null;
  samples.forEach((s,i)=>{const t=Number(s[0])||0;if(t>drawUntil&&i>0)return;const rpm=Number(s[8])||0;const x=left+chartW*(t/tmax),y=bottom-chartH*(rpm/rpmmax)*.88;if(!last)ctx.moveTo(x,y);else ctx.lineTo(x,y);last=[x,y];});ctx.stroke();
  if(last){ctx.fillStyle="#1d1d1f";ctx.beginPath();ctx.arc(last[0],last[1],3.3*dpr,0,Math.PI*2);ctx.fill();}
  ctx.fillStyle="#1d1d1f";ctx.font=`600 ${12*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;ctx.textAlign="right";ctx.fillText(`${rpmmax.toFixed(0)} rpm max`,right,top+13*dpr);ctx.restore();
}

function frame(now){
  const dpr=resize();ctx.clearRect(0,0,width,height);ctx.fillStyle="#fff";ctx.fillRect(0,0,width,height);
  const cycle=now%SCENE_TOTAL_MS;let scene=0,local=cycle,duration=SCENE_MODEL_MS;
  if(cycle>=SCENE_MODEL_MS&&cycle<SCENE_MODEL_MS+SCENE_WIND_MS){scene=1;local=cycle-SCENE_MODEL_MS;duration=SCENE_WIND_MS;}
  else if(cycle>=SCENE_MODEL_MS+SCENE_WIND_MS){scene=2;local=cycle-SCENE_MODEL_MS-SCENE_WIND_MS;duration=SCENE_RPM_MS;}
  const alpha=fadeWindow(local,duration);
  if(scene===0){
    setScene(0,"1. Winning geometry","Canonical physical orientation: TOP is +Z; the released rotor descends toward −Z.","current best geometry · same pose used by wind tunnel");
    const spin=now*CANONICAL_SPIN_RATE, scaleMul=CANONICAL_SCALE, offsetY=8*dpr;
    drawRotor(now,alpha,dpr,{spin,scaleMul,offsetY,cameraPitch:CANONICAL_CAMERA_PITCH});
    drawModelReference(spin,alpha,dpr,scaleMul,offsetY);
  }
  else if(scene===1){setScene(1,"2. Wind tunnel","Same pose and camera. Rotor descends toward −Z; relative airflow enters from below toward +Z.","relative airflow = −(v + ω × r) · central-body drag · not CFD");drawWindScene(now,local,duration,alpha,dpr);}
  else {setScene(2,"3. Autorotation","Released from rest at 0 RPM. The rotor descends toward −Z and spins itself up about Z.","RPM over simulated descent time");drawRpmScene(local,duration,alpha,dpr);}
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
